// === Tab: mySketch ===
// Click within the image to toggle
// the gradient colors and motion
// Note: for an alternative approach to the same example,
// involving changing uniforms please refer to:
// https://p5js.org/reference/#/p5.Shader/setUniform

let redCyan;
let orangeBlue;
let showRedCyan = false;

function preload() {
  // note that we are using two instances
  // of the same vertex and fragment shaders
  redCyan = loadShader('https://openprocessing.org/sketch/818528/files/shader.vert', 'shader-gradient.frag');
  orangeBlue = loadShader('https://openprocessing.org/sketch/818528/files/shader.vert', 'shader-gradient.frag');
	//img = loadImage('https://openprocessing.org/sketch/818528/files/shadgradjpg.JPG');
}

function setup() {
  createCanvas(1194, 834, WEBGL);

  // initialize the colors for redGreen shader
  shader(redCyan);
  redCyan.setUniform('colorCenter', [1.0, 0.0, 0.0]);
  redCyan.setUniform('colorBackground', [0.0, 1.0, 1.0]);

  // initialize the colors for orangeBlue shader
  shader(orangeBlue);
  orangeBlue.setUniform('colorCenter', [1.0, 0.5, 0.0]);
  orangeBlue.setUniform('colorBackground', [0.226, 0.0, 0.615]);
  noStroke();
}

function draw() {
	background(0);
  //image(img, -width/2, - height/2,width, height);

  // update the offset values for each shader,
  // moving orangeBlue in vertical and redGreen
  // in horizontal direction
  orangeBlue.setUniform('offset', [0, sin(millis() / 1500) + 1]);
  redCyan.setUniform('offset', [sin(millis() / 1000), 1]);

  if (showRedCyan === true) {
    shader(redCyan);
  } else {
    shader(orangeBlue);
  }
  quad(-1, -1, 1, -1, 1, 1, -1, 1);
}

function mouseClicked() {
  showRedCyan = !showRedCyan;
}

